item.aggregated_output:
            say(f"{rel}: a 'refine' QC must propose a new 'label'")
    for i, t in enumerate(c.get("tests", [])):
        proto = LEGACY.get(t.get("protocol"), t.get("protocol"))
        if proto not in PROTOCOLS:
